"use client";
/* Meh, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Meh(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("meh"); }, []);
  return React.createElement("piix-pal", { "pal": "meh", ...piixAttrs(props) });
}

export default Meh;
